VERSION = '2.0.0-free'
MIN_INTERVAL = 0.05
CHECK_URL = 'https://discord.com/api/v10/unique-username/username-attempt-unauthed'
ART_B64 = ''
ART = base64.b64decode(ART_B64)
ALPHABETS = {'letters': string.ascii_lowercase,
             'mixed': string.ascii_lowercase + string.digits,
             'extended': string.ascii_lowercase + string.digits + '._'}
LOG = logging.getLogger('nezzx')
