def new_config(length=4, alphabet='mixed', interval=5, custom=None):
    total = len(ALPHABETS[alphabet]) ** length
    step = secrets.randbelow(total - 1) + 1
    while math.gcd(step, total) != 1:
        step = secrets.randbelow(total - 1) + 1
    return {'length': length, 'alphabet': alphabet, 'interval': max(MIN_INTERVAL, interval),
            'custom': custom or [], 'cursor': 0, 'offset': secrets.randbelow(total), 'step': step}

def valid_name(value, length):
    return isinstance(value, str) and len(value) == length and re.fullmatch(r'[a-z0-9._]+', value) is not None and '..' not in value

def next_name(config):
    """Перестановка пространства имён без повторов в рамках прохода."""
    custom = config.get('custom', [])
    alphabet = ALPHABETS[config['alphabet']]
    total = len(custom) if custom else len(alphabet) ** config['length']
    while config['cursor'] < total:
        index = config['cursor']
        config['cursor'] += 1
        if custom:
            return custom[index]
        number = (config['offset'] + config['step'] * index) % total
        chars = []
        for _ in range(config['length']):
            number, remainder = divmod(number, len(alphabet))
            chars.append(alphabet[remainder])
        name = ''.join(reversed(chars))
        if valid_name(name, config['length']):
            return name
    return None

def safe_https(url):
    try:
        p = urllib.parse.urlsplit(url)
        return p.scheme == 'https' and bool(p.hostname) and not p.username and not p.password and not any(ord(c) < 32 for c in url)
    except ValueError:
        return False

def webhook_url(value):
    value = value.strip()
    p = urllib.parse.urlsplit(value)
    if not safe_https(value) or p.hostname not in {'discord.com', 'discordapp.com', 'canary.discord.com', 'ptb.discord.com'} or p.port not in (None, 443):
        raise ValueError('Нужен HTTPS-вебхук Discord.')
    if not re.fullmatch(r'/api/(?:v\d+/)?webhooks/\d{10,30}/[A-Za-z0-9_-]{20,250}', p.path):
        raise ValueError('Неверный адрес вебхука Discord.')
    query = urllib.parse.parse_qs(p.query)
    params = {'wait': 'true', 'with_components': 'true'}
    if 'thread_id' in query:
        tid = query['thread_id'][0]
        if not re.fullmatch(r'\d{10,30}', tid):
            raise ValueError('Неверный ID ветки.')
        params['thread_id'] = tid
    return urllib.parse.urlunsplit(('https', p.netloc, p.path, urllib.parse.urlencode(params), ''))

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

def http_post(url, body, content_type='application/json'):
    req = urllib.request.Request(url, data=body, headers={
        'Content-Type': content_type,
        'User-Agent': 'DiscordBot (https://discord.com/developers/docs, 1.0.0) NEZZX-Monitor'}, method='POST')
    try:
        with opener.open(req, timeout=15) as response:
            return response.status, dict(response.headers.items()), response.read(131072)
    except urllib.error.HTTPError as exc:
        return exc.code, dict(exc.headers.items()), exc.read(131072)
    except (urllib.error.URLError, TimeoutError, OSError):
        return 0, {}, b''

def json_object(raw):
    try:
        value = json.loads(raw)
        return value if isinstance(value, dict) else {}
    except (ValueError, UnicodeError, TypeError):
        return {}

def response_delay(headers, body, fallback=30):
    headers = {k.lower(): v for k, v in headers.items()}
    values = [fallback]
    # При 429 серверная пауза важнее нашей стартовой скорости.
    for v in (body.get('retry_after'), headers.get('retry-after'), headers.get('x-ratelimit-reset-after')):
        try:
            seconds = float(v)
            if math.isfinite(seconds) and seconds >= 0:
                values.append(seconds)
        except (TypeError, ValueError):
            pass
    return max(values) + 0.5

def parse_check(status, headers, raw):
    body = json_object(raw)
    if status == 429:
        return 'limited', response_delay(headers, body), 'Discord ограничил частоту; ожидание по Retry-After.'
    if status in (401, 403, 404) or 'captcha_key' in body:
        return 'blocked', 0, f'Discord HTTP {status}: проверка недоступна; поиск остановлен.'
    if status == 400:
        return 'invalid', MIN_INTERVAL, 'Discord отклонил формат имени.'
    if status == 200 and type(body.get('taken')) is bool:
        h = {k.lower(): v for k, v in headers.items()}
        pause = response_delay(headers, {}, 0) if h.get('x-ratelimit-remaining') == '0' else 0
        return ('taken' if body['taken'] else 'available'), pause, ''
    return 'error', 0, f'Неопределённый ответ Discord (HTTP {status or "network"}); находка не засчитана.'

def multipart(payload):
    boundary = 'nezzx' + secrets.token_hex(16)
    body = (f'--{boundary}\r\nContent-Disposition: form-data; name="payload_json"\r\n'
            f'Content-Type: application/json\r\n\r\n').encode()
    body += json.dumps(payload, ensure_ascii=False).encode() + b'\r\n'
    body += (f'--{boundary}\r\nContent-Disposition: form-data; name="files[0]"; filename="nezzx.jpg"\r\n'
             f'Content-Type: image/jpeg\r\n\r\n').encode()
    body += ART + f'\r\n--{boundary}--\r\n'.encode()
    return body, 'multipart/form-data; boundary=' + boundary

