class Store:
    def __init__(self, path):
        self.lock = threading.RLock()
        self.process_id = os.getpid()
        self.conn = sqlite3.connect(path, check_same_thread=False, timeout=20)
        self.conn.row_factory = sqlite3.Row
        with self.lock:
            self.conn.executescript('''
              PRAGMA journal_mode=WAL;
              PRAGMA busy_timeout=20000;
              CREATE TABLE IF NOT EXISTS lanes (
                length INTEGER PRIMARY KEY CHECK(length IN (3,4)), config TEXT NOT NULL,
                running INTEGER DEFAULT 1, due REAL DEFAULT 0, checked INTEGER DEFAULT 0,
                taken INTEGER DEFAULT 0, errors INTEGER DEFAULT 0, failures INTEGER DEFAULT 0,
                pending TEXT DEFAULT '', confirm INTEGER DEFAULT 0, reason TEXT DEFAULT 'Идёт поиск');
              CREATE TABLE IF NOT EXISTS hits (
                id INTEGER PRIMARY KEY AUTOINCREMENT, length INTEGER NOT NULL,
                username TEXT NOT NULL, created REAL NOT NULL,
                delivery TEXT DEFAULT 'pending', tries INTEGER DEFAULT 0,
                due REAL DEFAULT 0, message_id TEXT DEFAULT '', test INTEGER DEFAULT 0);
              CREATE UNIQUE INDEX IF NOT EXISTS unique_real_hit ON hits(length,username) WHERE test=0;
              CREATE INDEX IF NOT EXISTS queued_hits ON hits(length,delivery,due);
              CREATE TABLE IF NOT EXISTS events (
                id INTEGER PRIMARY KEY AUTOINCREMENT, length INTEGER NOT NULL,
                created REAL NOT NULL, kind TEXT NOT NULL, text TEXT NOT NULL);
            ''')
            for length in (3, 4):
                self.conn.execute('INSERT OR IGNORE INTO lanes(length,config) VALUES(?,?)',
                                  (length, json.dumps(new_config(length))))
            self.conn.commit()

    def all(self, sql, args=()):
        with self.lock:
            return [dict(row) for row in self.conn.execute(sql, args).fetchall()]

    def one(self, sql, args=()):
        rows = self.all(sql, args)
        return rows[0] if rows else None

    def write(self, sql, args=()):
        with self.lock:
            cursor = self.conn.execute(sql, args)
            self.conn.commit()
            return cursor.rowcount

    def lane(self, length):
        return self.one('SELECT * FROM lanes WHERE length=?', (length,))

    def event(self, length, kind, text):
        with self.lock:
            self.conn.execute('INSERT INTO events(length,created,kind,text) VALUES(?,?,?,?)',
                              (length, time.time(), kind, str(text)[:350]))
            self.conn.execute('DELETE FROM events WHERE id NOT IN (SELECT id FROM events ORDER BY id DESC LIMIT 200)')
            self.conn.commit()


db = Store(str(DATA_DIR / 'state.sqlite3'))


