@app.before_request
def csrf_guard():
    if request.path in {'/healthz', '/art.jpg', '/favicon.ico'}:
        return None
    if 'csrf' not in session:
        session['csrf'] = secrets.token_urlsafe(32)
    if request.method == 'POST':
        token = request.headers.get('X-CSRF-Token', '')
        if not hmac.compare_digest(token, session['csrf']):
            return jsonify(error='Сеанс обновился. Перезагрузи страницу.'), 403


@app.after_request
def response_headers(response):
    response.headers['X-Content-Type-Options'] = 'nosniff'
    response.headers['X-Frame-Options'] = 'DENY'
    response.headers['Referrer-Policy'] = 'no-referrer'
    response.headers['Cache-Control'] = 'public, max-age=86400' if request.path == '/art.jpg' else 'no-store'
    response.headers['Content-Security-Policy'] = "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'"
    return response


def require_owner(function):
    @wraps(function)
    def wrapped(*args, **kwargs):
        if not session.get('owner'):
            return jsonify(error='Открой ссылку управления из журнала запуска Render.'), 403
        return function(*args, **kwargs)
    return wrapped


def body_json():
    value = request.get_json(silent=True)
    if not isinstance(value, dict):
        raise ValueError('Нужен JSON-объект.')
    return value


def request_length(data):
    try:
        length = int(data.get('length', 0))
    except (TypeError, ValueError):
        raise ValueError('Нужна длина 3 или 4.')
    if length not in (3, 4):
        raise ValueError('Нужна длина 3 или 4.')
    return length


@app.errorhandler(ValueError)
def bad_request(exc):
    return jsonify(error=str(exc)), 400


@app.errorhandler(Exception)
def unexpected(exc):
    if isinstance(exc, HTTPException):
        return jsonify(error=exc.description), exc.code
    LOG.exception('Ошибка обработки запроса')
    return jsonify(error='Внутренняя ошибка. Подробности в журнале сервиса.'), 500


@app.get('/healthz')
def health():
    return jsonify(ok=True, version=VERSION)


@app.get('/art.jpg')
def artwork():
    return Response(ART, mimetype='image/jpeg')


@app.get('/favicon.ico')
def favicon():
    return Response(status=204)


@app.get('/')
def home():
    return Response(HTML, mimetype='text/html')


@app.get('/api/state')
def state():
    if not session.get('owner'):
        return jsonify(authorized=False, csrf=session['csrf'])
    lanes = []
    for row in db.all('SELECT * FROM lanes ORDER BY length'):
        config = json.loads(row['config'])
        row['config'] = {key: config[key] for key in ('length', 'alphabet', 'interval', 'custom')}
        row['found'] = db.one('SELECT COUNT(*) AS n FROM hits WHERE length=? AND test=0', (row['length'],))['n']
        row['running'] = bool(row['running'])
        lanes.append(row)
    return jsonify(authorized=True, csrf=session['csrf'], lanes=lanes,
                   cooldown=max(0, math.ceil(max(engine.global_after, max(engine.check_after.values())) - time.time())),
                   hits=db.all('SELECT id,length,username,created,delivery,test FROM hits ORDER BY id DESC LIMIT 150'),
                   events=db.all('SELECT length,created,kind,text FROM events ORDER BY id DESC LIMIT 70'))


@app.post('/api/login')
def login():
    key = str(body_json().get('key', ''))
    if not hmac.compare_digest(key, CONTROL_KEY):
        return jsonify(error='Неверная ссылка управления. Возьми её из журнала запуска сервиса.'), 403
    session.clear()
    session['owner'] = True
    session['csrf'] = secrets.token_urlsafe(32)
    session.permanent = True
    return jsonify(ok=True)


@app.post('/api/logout')
def logout():
    session.clear()
    return jsonify(ok=True)


@app.post('/api/start')
@require_owner
def start_scan():
    length = request_length(body_json())
    db.write('UPDATE lanes SET running=1,due=?,failures=0,reason=? WHERE length=?', (time.time(), 'Идёт поиск', length))
    db.event(length, 'info', f'Поиск {length} символов запущен бесплатно.')
    return jsonify(ok=True)


@app.post('/api/stop')
@require_owner
def stop_scan():
    length = request_length(body_json())
    db.write('UPDATE lanes SET running=0,reason=? WHERE length=?', ('Поиск остановлен', length))
    return jsonify(ok=True)


@app.post('/api/settings')
@require_owner
def settings():
    data = body_json()
    length = request_length(data)
    lane = db.lane(length)
    if lane['running']:
        return jsonify(error=f'Сначала останови поиск {length} символов.'), 409
    alphabet = data.get('alphabet', 'mixed')
    if alphabet not in ALPHABETS:
        raise ValueError('Неизвестный алфавит.')
    try:
        interval = float(data.get('interval', MIN_INTERVAL))
    except (ValueError, TypeError):
        raise ValueError('Проверь интервал.')
    if not math.isfinite(interval) or not (0.1 <= interval <= 3600):
        raise ValueError('Интервал: от 0.1 до 3600 секунд (рекомендуется 0.1-1.0).')
    text = data.get('custom', '')
    if not isinstance(text, str) or len(text) > 12000:
        raise ValueError('Список слишком большой.')
    custom = list(dict.fromkeys(name.lower().lstrip('@') for name in re.split(r'[\s,;]+', text.strip()) if name))
    if len(custom) > 1000 or any(not valid_name(name, length) for name in custom):
        raise ValueError(f'До 1000 ников по {length} символа: a-z, 0-9, точка, _. Две точки подряд нельзя.')
    old = json.loads(lane['config'])
    same_space = old['alphabet'] == alphabet and old['custom'] == custom
    # Завершённый пользовательский список можно запустить заново повторным сохранением.
    if custom and old['cursor'] >= len(custom) and not lane['pending']:
        same_space = False
    config = dict(old, interval=interval) if same_space else new_config(length, alphabet, interval, custom)
    db.write('UPDATE lanes SET config=?,pending=?,confirm=?,reason=? WHERE length=?',
             (json.dumps(config), lane['pending'] if same_space else '', lane['confirm'] if same_space else 0, 'Настройки сохранены', length))
    return jsonify(ok=True)


@app.post('/api/webhook-test')
@require_owner
def test_webhook():
    length = request_length(body_json())
    recent = db.one('SELECT id FROM hits WHERE length=? AND test=1 AND created>?', (length, time.time() - 30))
    if recent:
        return jsonify(error='Тест каждого вебхука можно отправлять раз в 30 секунд.'), 429
    db.write('INSERT INTO hits(length,username,created,due,test) VALUES(?,?,?,?,1)',
             (length, 'abc' if length == 3 else 'abcd', time.time(), time.time()))
    return jsonify(ok=True, message=f'Тест WEBHOOK_{length} в очереди.')


@app.post('/api/retry')
@require_owner
def retry():
    length = request_length(body_json())
    db.write('UPDATE hits SET delivery="pending",tries=0,due=? WHERE length=? AND delivery="failed"', (time.time(), length))
    return jsonify(ok=True)


@app.get('/api/export')
@require_owner
def export():
    stream = io.StringIO()
    writer = csv.writer(stream)
    writer.writerow(['username', 'length', 'found_at_utc', 'webhook_status'])
    for row in db.all('SELECT username,length,created,delivery FROM hits WHERE test=0 ORDER BY id DESC'):
        writer.writerow([row['username'], row['length'], datetime.fromtimestamp(row['created'], timezone.utc).isoformat(), row['delivery']])
    return Response('\ufeff' + stream.getvalue(), mimetype='text/csv', headers={'Content-Disposition': 'attachment; filename=nezzx_finds.csv'})


